SET client_encoding = 'UTF8';










SELECT setval('public.associations_id_seq', (SELECT max(id) FROM public.associations));
SELECT setval('public.descriptions_id_seq', (SELECT max(id) FROM public.descriptions));
SELECT setval('public.methods_id_seq', (SELECT max(id) FROM public.methods));
SELECT setval('public.proteins_id_seq', (SELECT max(id) FROM public.proteins));
SELECT setval('public.runs_id_seq', (SELECT max(id) FROM public.runs));
SELECT setval('public.taxon_pk_seq', (SELECT max(taxon_id) FROM public.taxon));
